import os
import re
from typing import Any, Dict, List, Optional, Tuple

import requests


class TextContentSafety:
    """
    Redacts unsafe spans from text using the Perspective API.
    Requires:
      - PERSPECTIVE_API_KEY environment variable
    """

    API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    def __init__(
        self,
        api_key: Optional[str] = None,
        requested_attributes: Optional[Dict[str, Dict[str, Any]]] = None,
        score_threshold: float = 0.70,
        timeout: float = 20.0,
    ):
        self.api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing PERSPECTIVE_API_KEY")

        self.requested_attributes = requested_attributes or {
            "TOXICITY": {},
            "SEVERE_TOXICITY": {},
            "IDENTITY_ATTACK": {},
            "INSULT": {},
            "PROFANITY": {},
            "THREAT": {},
            "SEXUALLY_EXPLICIT": {},
        }
        self.score_threshold = score_threshold
        self.timeout = timeout

    def _analyze(self, text: str) -> Dict[str, Any]:
        payload = {
            "comment": {"text": text},
            "requestedAttributes": self.requested_attributes,
            "doNotStore": True,
            "spanAnnotations": True,
        }
        params = {"key": self.api_key}
        resp = requests.post(self.API_URL, params=params, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        return resp.json()

    def _extract_unsafe_spans(self, analysis: Dict[str, Any], text: str) -> List[Tuple[int, int, str, float]]:
        spans: List[Tuple[int, int, str, float]] = []
        attr_map = analysis.get("attributeScores", {}) or {}

        for attr_name, attr_payload in attr_map.items():
            summary = (attr_payload or {}).get("summaryScore", {}) or {}
            score = float(summary.get("value", 0.0) or 0.0)
            if score < self.score_threshold:
                continue

            span_scores = (attr_payload or {}).get("spanScores", []) or []
            for span in span_scores:
                begin = int(span.get("begin", 0) or 0)
                end = int(span.get("end", 0) or 0)
                span_score = float(((span or {}).get("score", {}) or {}).get("value", 0.0) or 0.0)
                if span_score >= self.score_threshold and 0 <= begin < end <= len(text):
                    spans.append((begin, end, attr_name, span_score))

        spans.sort(key=lambda x: (x[0], x[1]))
        merged: List[Tuple[int, int, str, float]] = []
        for begin, end, attr_name, score in spans:
            if not merged or begin > merged[-1][1]:
                merged.append((begin, end, attr_name, score))
            else:
                prev_begin, prev_end, prev_attr, prev_score = merged[-1]
                merged[-1] = (
                    prev_begin,
                    max(prev_end, end),
                    prev_attr if prev_score >= score else attr_name,
                    max(prev_score, score),
                )
        return merged

    def flag(self, text: str) -> Dict[str, Any]:
        analysis = self._analyze(text)
        spans = self._extract_unsafe_spans(analysis, text)
        return {
            "unsafe": bool(spans),
            "spans": [
                {
                    "start": begin,
                    "end": end,
                    "label": label,
                    "score": score,
                    "text": text[begin:end],
                }
                for begin, end, label, score in spans
            ],
            "analysis": analysis,
        }

    def redact(self, text: str, replacement: str = "[REDACTED]") -> str:
        flagged = self.flag(text)
        spans = flagged["spans"]
        if not spans:
            return text

        redacted_parts = []
        last_idx = 0
        for span in spans:
            start, end = span["start"], span["end"]
            if start < last_idx:
                continue
            redacted_parts.append(text[last_idx:start])
            redacted_parts.append(replacement)
            last_idx = end
        redacted_parts.append(text[last_idx:])
        return "".join(redacted_parts)

    def redact_with_spans(self, text: str, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        flagged = self.flag(text)
        return {
            "text": self.redact(text, replacement=replacement),
            "unsafe": flagged["unsafe"],
            "spans": flagged["spans"],
        }


def flag_unsafe_spans(text: str, score_threshold: float = 0.70) -> Dict[str, Any]:
    return TextContentSafety(score_threshold=score_threshold).flag(text)


def redact_unsafe_spans(text: str, replacement: str = "[REDACTED]", score_threshold: float = 0.70) -> str:
    return TextContentSafety(score_threshold=score_threshold).redact(text, replacement=replacement)
